{"python_code":"def _x_cylinder(radius, start, end):
    return Part.makeCylinder(
        radius, end - start,
        App.Vector(start, 0, 0), App.Vector(1, 0, 0)
    )


def _finish(shape, frame):
    shape = shape.removeSplitter()
    shape.Placement = frame.multiply(shape.Placement)
    if len(shape.Solids) != 1 or not shape.isValid():
        raise ValueError('Parameters did not produce a valid single solid')
    return shape


def build(p, frame):
    x0 = p['x0']
    shoulder = p['shoulder']
    sleeve_end = x0 + p['sleeve_length']
    bearing_end = p['bearing_end']

    bearing_blank = _x_cylinder(p['outer_radius'], shoulder, bearing_end)
    bearing_void = _x_cylinder(
        p['rear_bore'], shoulder, p['relief_start']
    ).multiFuse([
        _x_cylinder(p['relief_radius'], p['relief_start'], p['relief_end']),
        _x_cylinder(p['front_bore'], p['relief_end'], bearing_end)
    ])
    bearing = bearing_blank.cut(bearing_void)

    sleeve_blank = _x_cylinder(p['sleeve_radius'], x0, sleeve_end).fuse(
        _x_cylinder(p['outer_radius'], x0, shoulder)
    )
    void_end = max(sleeve_end, shoulder)
    sleeve_void = _x_cylinder(p['sleeve_bore'], x0, void_end)

    count = int(p['groove_count'])
    if count < 0 or count != p['groove_count']:
        raise ValueError('groove_count must be a nonnegative integer')

    grooves = []
    for i in range(count):
        groove = Part.makeBox(
            void_end - x0, p['groove_root'], p['groove_width'],
            App.Vector(x0, 0, -p['groove_width'] / 2.0)
        )
        groove.rotate(
            App.Vector(0, 0, 0), App.Vector(1, 0, 0),
            360.0 * i / count
        )
        grooves.append(groove)
    if grooves:
        sleeve_void = sleeve_void.multiFuse(grooves)
    sleeve = sleeve_blank.cut(sleeve_void)

    return {
        'bearing': _finish(bearing, frame),
        'sleeve': _finish(sleeve, frame)
    }
","explanation":"Builds the stepped bearing and nested flanged sleeve in local coordinates. The sleeve void unions a cylindrical bore with evenly rotated rectangular grooves starting along +Y. Each finished shape receives the frame exactly once and is checked for validity and one solid. Not executed in this session."}
